function tn(f,d,t,v,ty){const a=au();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=ty||'sine';o.frequency.value=f;const s=a.currentTime+(t||0);g.gain.setValueAtTime(v||.15,s);g.gain.exponentialRampToValueAtTime(.001,s+d);o.connect(g);g.connect(a.destination);o.start(s);o.stop(s+d)}
