/* ===== PERGUNTAS ===== */
function mk(op,d){const mx=d<3?10*d+5:25*d;let a,b,t,x,ex,e,k;
if(op.startsWith('word')){k=op.length>4?+op[4]:R(0,3);op='word';const nm=pick(['Ana','Pedro','Luiza','Caio','Marta']);
 if(k==0){a=R(5,mx);b=R(2,mx);x=a+b;ex=`${a}+${b}`;t=`${nm} tinha ${a} figurinhas e ganhou ${b}. Com quantas ficou?`;e=`Ganhar é somar: ${a} + ${b} = ${x}.`}
 else if(k==1){a=R(8,mx+5);b=R(2,a-1);x=a-b;ex=`${a}-${b}`;t=`${nm} tinha ${a} reais e gastou ${b}. Quanto sobrou?`;e=`Gastar é tirar: ${a} − ${b} = ${x}.`}
 else if(k==2){a=R(2,2+2*d);b=R(2,Math.min(12,3+2*d));x=a*b;ex=`${a}*${b}`;t=`Uma caixa tem ${a} lápis. Quantos lápis há em ${b} caixas?`;e=`${b} caixas com ${a} lápis: ${a} × ${b} = ${x}.`}
 else{b=R(2,2+2*d);x=R(2,Math.min(12,3+2*d));a=x*b;ex=`${a}/${b}`;t=`${a} balas foram divididas igualmente entre ${b} amigos. Quantas cada um recebeu?`;e=`Repartir é dividir: ${a} ÷ ${b} = ${x}, pois ${b} × ${x} = ${a}.`}}
else if(op=='add'){a=R(2,mx);b=R(2,mx);x=a+b;ex=`${a}+${b}`;t=`${a} + ${b} = ?`;e=`Somando ${a} com ${b} temos ${x}.`}
else if(op=='sub'){a=R(6,mx+5);b=R(1,a-1);x=a-b;ex=`${a}-${b}`;t=`${a} − ${b} = ?`;e=`Tirando ${b} de ${a} sobram ${x}. Confira: ${x} + ${b} = ${a}.`}
else if(op=='mul'){a=R(2,2+2*d);b=R(2,Math.min(12,3+2*d));x=a*b;ex=`${a}*${b}`;t=`${a} × ${b} = ?`;e=`${a} × ${b} é somar ${a} por ${b} vezes: ${x}.`}
else if(op=='div'){b=R(2,2+2*d);x=R(2,Math.min(12,3+2*d));a=x*b;ex=`${a}/${b}`;t=`${a} ÷ ${b} = ?`;e=`Divisão é o inverso da multiplicação: ${b} × ${x} = ${a}, então ${a} ÷ ${b} = ${x}.`}
else if(op=='tab'){a=R(2,10);b=R(1,10);x=a*b;ex=`${a}*${b}`;t=`${a} × ${b} = ?`;e=`Tabuada do ${a}: ${a} × ${b} = ${x}.`}
else if(op=='frac'){b=R(2,5);const n=R(1,b-1),base=b*R(2,2+2*d);x=base/b*n;ex=`${base}/${b}*${n}`;t=`Quanto é ${n}/${b} de ${base}?`;e=`Divida ${base} em ${b} partes iguais: ${base/b} cada. Pegue ${n} parte(s): ${x}.`}
else{const p=pick([10,20,25,50]),base=20*R(1,2+2*d);x=base*p/100;ex=`${base}*${p}/100`;t=`Quanto é ${p}% de ${base}?`;e=`${p}% de ${base} = ${p}/100 × ${base} = ${x}. (10% é dividir por 10; 50% é a metade.)`}
return{op,t,a:x,ex,e}}
function dist(x){const s=shuf([1,-1,2,-2,3,-3,5,-5,10,-10].map(k=>x+k)).filter(v=>v>=0&&v!=x).slice(0,3);while(s.length<3){const v=x+R(11,30);if(!s.includes(v))s.push(v)}return s}
function genQ(op,d){for(let i=0;i<30;i++){const q=mk(op,d),o=[q.a,...dist(q.a)];let ok=new Set(o).size==4&&Number.isInteger(q.a);try{ok=ok&&Function('return '+q.ex)()===q.a}catch(e){ok=false}if(ok){q.o=shuf(o);return q}}return genQ('add',1)}
