function rec(op,ok){const o=op.startsWith('word')?'word':op;const s=S.st[o]=S.st[o]||[0,0];s[0]++;S.tot[0]++;const h=S.hist[S.lv]=S.hist[S.lv]||[0,0];h[0]++;if(ok){s[1]++;S.tot[1]++;h[1]++}S.started=1}
